var limit = 30;
var composite = [];
var primes = [];
for (var i = 2; i <= limit; i++) {
  if (!composite[i]) {
    primes.push(i);
    for (var j = i * i; j <= limit; j += i) {
      composite[j] = true;
    }
  }
}
console.log(primes);
